import type {Dataset} from '@/lib/sources';
const money=(n:number,digits=0)=>Number.isFinite(n)?n.toLocaleString('he-IL',{maximumFractionDigits:digits,minimumFractionDigits:digits}):'—';
const percent=(n:number,digits=1)=>`${money(n,digits)}%`;
const COLORS=['#0a9396','#03071e','#00cecb','#789f92','#b45309'];
const kinds:TrackKind[]=['fixed','prime','variable','indexed','variableIndexed'];
const methods={annuity:'שפיצר',equal:'קרן שווה',balloonPartial:'בולט חלקי',balloonFull:'בולט מלא'};
const latestCurve=(d:Dataset)=>d.curves.filter(c=>c.average==='קלנדרי').at(-1)!;
function sourceRates(d:Dataset,bank:string,month:string){const row=d.rates.find(r=>r.bank===bank&&r.month===month);return Object.fromEntries(kinds.map(k=>[k,row?.rates[k as keyof typeof row.rates]!=null?effectiveToNominal(row!.rates[k as keyof typeof row.rates]!):NaN]));}
const initialRates=sourceRates(initial,'סך מערכת',initial.equatorEnd);
function Pick({label,value,onChange,options}:{label:string;value:string;onChange:(s:string)=>void;options:([string,string])[]}){const id=useId();return <div className="field"><label htmlFor={id}>{label}</label><Select dir="rtl" value={value} onValueChange={onChange}><SelectTrigger id={id} aria-label={label} className="w-full"><SelectValue/></SelectTrigger><SelectContent position="popper">{options.map(([v,n])=><SelectItem key={v} value={v}>{n}</SelectItem>)}</SelectContent></Select></div>}
function Num({label,value,onChange,min=0,max,step=1,help}:{label:string;value:number;onChange:(v:number)=>void;min?:number;max?:number;step?:number;help?:string}){return <label className="field">{label}<input className="field-input" aria-label={label} type="number" min={min} max={max} step={step} value={Number.isFinite(value)?value:''} onChange={e=>onChange(e.target.value===''?NaN:Number(e.target.value))}/>{help&&<small>{help}</small>}</label>}
function Toggle({label,checked,onChange}:{label:string;checked:boolean;onChange:(b:boolean)=>void}){const id=useId();return <div className="toggle"><label htmlFor={id}>{label}</label><Switch id={id} dir="ltr" checked={checked} onCheckedChange={onChange}/></div>}
function download(name:string,body:string,type='application/json'){const u=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);}
async function api(url:string,body?:unknown){const r=await fetch(url,body===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data:any=await r.json();if(!r.ok)throw Error(data.error??'הפעולה לא הושלמה');return data;}
function Chart({data,keys,budget}:{data:Record<string,any>[];keys:([string,string,string])[];budget?:number}){return <div className="chart" dir="ltr"><ResponsiveContainer width="100%" height="100%"><LineChart data={data} margin={{top:10,right:20,left:2,bottom:0}}><CartesianGrid vertical={false} stroke="#e9edf0"/><XAxis interval="preserveStartEnd" dataKey="x" axisLine={false} tickLine={false} minTickGap={35} tick={{fill:'#697386',fontSize:12}}/><YAxis axisLine={false} tickLine={false} width={65} tickFormatter={n=>money(n)} tick={{fill:'#697386',fontSize:12}}/><Tooltip contentStyle={{direction:'rtl',borderRadius:12,borderColor:'#dee1e7'}} formatter={(v:any)=>money(Number(v),2)}/><Legend wrapperStyle={{fontSize:13,paddingTop:12}}/>{budget? <ReferenceLine y={budget} stroke="#b45309" strokeDasharray="5 5"/>:null}{keys.map(([key,label,color])=><Line key={key} type="stepAfter" dataKey={key} name={label} stroke={color} strokeWidth={2.8} dot={false} isAnimationActive={false}/>)}</LineChart></ResponsiveContainer></div>}
export default function Studio(){
 const searchWorker=useRef<Worker|null>(null);useEffect(()=>()=>searchWorker.current?.terminate(),[]);
 const [provenance,setProvenance]=useState({sourceVersion:initial.id,sourceHashes:initial.sources.map(s=>({key:s.key,sha256:s.sha256,fetchedAt:s.fetchedAt}))});
 function pinSource(key:string){const source=data.sources.find(s=>s.key===key);if(source)setProvenance(p=>({sourceVersion:data.id,sourceHashes:[...p.sourceHashes.filter(s=>s.key!==key),{key:source.key,sha256:source.sha256,fetchedAt:source.fetchedAt}]}))}
 const [data,setData]=useState<Dataset>(initial);const [caseData,setCase]=useState<Case>(structuredClone(defaultCase));const [rates,setRates]=useState<Record<string,number>>(initialRates);const [bank,setBank]=useState('סך מערכת');const [tab,setTab]=useState('intake');const [cfg,setCfg]=useState<Config>(defaultConfig);const [forecast,setForecast]=useState<Forecast>({mode:'boi',curve:latestCurve(initial) as Curve,inflation:2,rateShock:0,shockMonth:13});
 const [tracks,setTracks]=useState<Track[]>(()=>[...kinds.slice(0,3).map((k,i)=>({...makeTrack(k,[480000,360000,360000][i],initialRates[k]),id:`initial-${k}`}))]);const [result,setResult]=useState<Optimization|null>(null);const [busy,setBusy]=useState(false);const [syncing,setSyncing]=useState(false);const [saved,setSaved]=useState<any[]>([]);const [approvedPolicy,setApprovedPolicy]=useState(initial.policy.currentInterest);const [selectedTrack,setSelectedTrack]=useState<string|null>(null);const [showSchedule,setShowSchedule]=useState(false);const [showImport,setShowImport]=useState(false);const [jsonInput,setJsonInput]=useState('');const [draft,setDraft]=useState<ReturnType<typeof mapWiseQuestionnaire>|null>(null);const [importError,setImportError]=useState('');const [scenarioShock,setScenarioShock]=useState(2);const [scenarioMonth,setScenarioMonth]=useState(13);const [marketMonth,setMarketMonth]=useState(initial.equatorEnd);const [marketKind,setMarketKind]=useState('fixed');const [marketBank,setMarketBank]=useState('סך מערכת');const [loadWarning,setLoadWarning]=useState('');const [versionLabel,setVersionLabel]=useState('טיוטה');const [persisting,setPersisting]=useState(false);
 const [researchScenario,setResearchScenario]=useState<ResearchScenario|null>(null);const [migrationNotice,setMigrationNotice]=useState('');
 const [showAllTerms,setShowAllTerms]=useState(false);const [selectedId,setSelectedId]=useState<string|null>(null);const [visibleCount,setVisibleCount]=useState(12);const [searchBase,setSearchBase]=useState<Track[]|null>(null);const [rateOrigin,setRateOrigin]=useState({bank:'סך מערכת',month:initial.equatorEnd,basis:'ממוצעי שוק'});
 const aff=useMemo(()=>affordability(caseData),[caseData]);const errors=caseErrors(caseData);const trackErrors=tracks.flatMap(t=>validateTrack(t).map(e=>`${TRACKS[t.kind]}: ${e}`));if(Math.abs(tracks.reduce((s,t)=>s+t.amount,0)-caseData.loan)>.01)trackErrors.push('סכומי המסלולים אינם מסתכמים לסכום המשכנתא');
 const summary=useMemo(()=>{try{if(trackErrors.length)return null;return summarize(tracks,forecast,caseData.fees)}catch{return null}},[tracks,forecast,caseData.fees,caseData.loan]);const shockSummary=useMemo(()=>{try{if(trackErrors.length)return null;return summarize(tracks,{...forecast,rateShock:scenarioShock,shockMonth:scenarioMonth},caseData.fees)}catch{return null}},[tracks,forecast,caseData.fees,caseData.loan,scenarioShock,scenarioMonth]);
 const eligibility=checkEligibility(caseData,tracks,summary?.ptiPayment,cfg,summary?.first,summary?.peak);
 const displayedCandidates=useMemo(()=>{const rows=result?.candidates??[];if(showAllTerms)return rows;const seen=new Set<string>();return rows.filter(c=>{const key=JSON.stringify(kinds.map(k=>Math.round(c.tracks.filter(t=>t.kind===k).reduce((n,t)=>n+t.amount,0))));if(seen.has(key))return false;seen.add(key);return true})},[result,showAllTerms]);
 const calculationErrors=[...new Set(eligibility.errors)];
 const updateCase=(p:Partial<Case>)=>{setCase(c=>({...c,...p}));setResult(null);setVersionLabel('טיוטה עם שינויים')};const updateCfg=(p:Partial<Config>)=>{setCfg(c=>({...c,...p}));setResult(null)};const updateTrack=(id:string,p:Partial<Track>)=>{setResult(null);setTracks(s=>s.map(t=>t.id===id?{...t,...p}:t));setVersionLabel('טיוטה עם שינויים')};
 useEffect(()=>{api('/api/data').then(r=>{setData(r.data);if(r.error)setLoadWarning(r.error)}).catch(()=>setLoadWarning('מוצגת תמונת הנתונים שנשמרה ב־8.10.2026; רענון מקורות אינו זמין כרגע'));api('/api/runs').then(r=>setSaved(r.runs)).catch(()=>{});api('/api/preferences').then(r=>{if(r.preferences)setApprovedPolicy(r.preferences.approvedPolicy)}).catch(()=>{});},[]);
 function run(nextRates=rates){
  setTab('workspace');setBusy(true);setResult(null);setVisibleCount(12);setSearchBase(structuredClone(tracks));searchWorker.current?.terminate();
  const done=()=>{searchWorker.current?.terminate();searchWorker.current=null;setBusy(false)};
  try{const worker=new OptimizerWorker();searchWorker.current=worker;
   worker.onmessage=({data}:{data:{result?:Optimization;error?:string}})=>{if(data.error){toast.error(data.error);done();return}const r=data.result!;setResult(r);if(r.candidates[0]){setTracks(r.candidates[0].tracks);setSelectedId(r.candidates[0].id);setVersionLabel('הרצה חדשה');toast.success(`נסרקו ${money(r.tested)} חלופות; ${money(r.feasible)} אומתו ועברו מגבלות`)}else toast.error(r.errors[0]);done()};
   worker.onerror=()=>{toast.error('החיפוש לא הושלם. ניתן להריץ מחדש.');done()};
   worker.postMessage({caseData,cfg,rates:nextRates,forecast,tracks});
  }catch(e){toast.error((e as Error).message);done()}
 }
 function applyResearch(horizon:number){try{const applied=applyResearchScenario(researchScenario?.baseRates??rates,horizon);setRates(applied.rates);setResearchScenario(applied.scenario);setRateOrigin(o=>({...o,basis:`תרחיש מחקר · ${horizon} חודשים · שינוי בריביות הקבועות`}));run(applied.rates)}catch(e){toast.error((e as Error).message)}}
 function state(){return {caseData,tracks,cfg,forecast,rates:Object.fromEntries(Object.entries(rates).filter(([,v])=>Number.isFinite(v))),bank:rateOrigin.bank,rateOrigin,scenarioShock,scenarioMonth,searchBase:result?searchBase:null,selectedId:result?selectedId:null,approvedPolicy,modelVersion:MODEL_VERSION,engineVersion:ENGINE_VERSION,rulesVersion:RULE_VERSION,researchScenario,...provenance,scope:result?.scope??'תמהיל בעריכה ידנית',summary:summary?{current:summary.current,complete:summary.complete,peak:summary.complete?summary.peak:null,total:summary.complete?summary.total:null,irr:summary.complete?summary.irr:null}:null};}
 async function save(){if(calculationErrors.length||!summary){toast.error(calculationErrors[0]??'נדרש להשלים את התמהיל');return}setPersisting(true);try{const r=await api('/api/runs',{id:crypto.randomUUID(),name:caseData.name,state:state()});setVersionLabel(`נשמר ${new Date(r.createdAt).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'})}`);setSaved((await api('/api/runs')).runs);toast.success('ההרצה נשמרה עם נתוני המקור והתחזית שלה')}catch(e){toast.error((e as Error).message)}finally{setPersisting(false)}}
 function restore(r:any){const s=r.payload;setResearchScenario(s.researchScenario??null);setMigrationNotice(s.modelVersion!==MODEL_VERSION?`נטענה גרסה שנשמרה במנוע ${s.modelVersion}. מוצג כעת חישוב מחדש במנוע ${MODEL_VERSION}; הסכום המקורי שנשמר היה ${s.summary?.total!=null?money(s.summary.total)+" ₪":"לא זמין"}. הרשומה המקורית נשמרת ללא שינוי.`:"");setProvenance({sourceVersion:s.sourceVersion,sourceHashes:s.sourceHashes});setCase(s.caseData);setTracks(s.tracks);setCfg(s.cfg);setForecast(s.forecast);setRates(s.rates);setBank(s.bank);setApprovedPolicy(s.approvedPolicy);setRateOrigin(s.rateOrigin??{bank:s.bank,month:'מקור שמור',basis:'גרסה קודמת'});setScenarioShock(s.scenarioShock??2);setScenarioMonth(s.scenarioMonth??13);setSelectedId(s.selectedId??null);setSearchBase(s.searchBase??null);setResult(s.searchBase&&s.modelVersion===MODEL_VERSION?optimize(s.caseData,s.cfg,s.rates,s.forecast,{baseTracks:s.searchBase}):null);setVersionLabel('גרסה שמורה · '+new Date(r.created_at).toLocaleDateString('he-IL'));setTab('workspace');toast.success(s.modelVersion===MODEL_VERSION?'הגרסה שוחזרה עם התחזית המקורית':'הקלט שוחזר וחושב מחדש; פרטי המעבר מוצגים מעל התמהיל')}
 async function sync(){setSyncing(true);try{const r=await api('/api/data',{});setData(r.data);setLoadWarning(r.errors?.join(' · ')??'');toast[r.errors?.length?'warning':'success'](r.errors?.length?'חלק מהמקורות עודכנו; מקורות שלא זמינים נשמרו בגרסתם הקודמת':'המקורות עודכנו. ההרצה הנוכחית נשארה על בסיס הנתונים שלה.')}catch(e){toast.error((e as Error).message)}finally{setSyncing(false)}}
 function applyMarket(){setResearchScenario(null);pinSource('equator');const rs=sourceRates(data,bank,data.equatorEnd);setRates(rs);setRateOrigin({bank,month:data.equatorEnd,basis:'ממוצעי שוק'});setResult(null);toast.success('נטענו ריביות ייחוס נומינליות לחיפוש; אינן הצעה אישית')}
 const curveOptions=data.curves.slice().reverse().map(c=>[c.id,`${c.year}/${String(c.month).padStart(2,'0')} · ${c.average}`] as [string,string]);const active=tracks.find(t=>t.id===selectedTrack);const chartData=summary?.rows.map(r=>({x:r.month,payment:r.regular,stress:shockSummary?.rows[r.month-1]?.regular??0,balance:r.balance}))??[];
 useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const life=new AbortController();Promise.resolve(context.registerTool({name:'read_mogi_calculation',description:'Read the current visible Mogi mortgage calculation, assumptions and validation errors. Does not save or change data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:(input:any)=>{if(!input||Object.keys(input).length)throw Error('No arguments are accepted');return {caseName:caseData.name,current:summary?.current,total:summary?.complete?summary.total:null,complete:summary?.complete??false,peak:summary?.complete?summary.peak:null,errors:calculationErrors,forecast:forecast.curve.id,modelVersion:MODEL_VERSION};}},{signal:life.signal})).catch(()=>{});return()=>life.abort()},[caseData,summary,forecast,calculationErrors.join('|')]);
 return <main className="app-shell"><Toaster position="bottom-left" richColors/><header className="topbar"><img src="/mogi-logo.png" alt="Mogi"/><strong>התמהיל האופטימלי</strong><span className="top-section">מרחב העבודה</span><span className="pill"><ShieldCheck size={15}/>גרסת עבודה פרטית</span><button className="secondary icon-button" onClick={save} disabled={persisting||busy}><Save size={16}/><span>שמירת גרסה</span></button></header><div className="breadcrumb"><span>{caseData.name} / רכישת דירה / אופטימיזציה</span><span>{versionLabel} · מנוע {ENGINE_VERSION}</span></div><div className="page-title"><div><p className="eyebrow">MOGI MORTGAGE STUDIO</p><h1>תמהיל שעובד בשבילך.</h1><p className="muted">בוחנים עלות, החזר ויציבות — ומבינים את המחיר של כל בחירה.</p></div><button className="primary icon-button" onClick={()=>run()} disabled={busy}><SlidersHorizontal size={18}/>{busy?'בוחן חלופות…':'חיפוש והשוואת תמהילים'}</button></div>
 {busy&&<div className="notice info" role="status">החיפוש פועל ברקע: סינון חלופות ואימות לוחות סילוקין מדויקים… <button className="text-button" onClick={()=>{searchWorker.current?.terminate();searchWorker.current=null;setBusy(false);toast.info("החיפוש בוטל")}}>ביטול החיפוש</button></div>}<fieldset disabled={busy} style={{border:0,padding:0,margin:0,minWidth:0}}><Tabs value={tab} onValueChange={setTab} dir="rtl"><TabsList variant="line" className="navigation">{[['intake','1 · נתוני התיק'],['algorithm','2 · ריביות ומגבלות'],['workspace','3 · השוואת תמהילים'],['scenarios','4 · בדיקת עמידות'],['market','ריביות ומקורות'],['integrations','חיבורים ו־Wise'],['history','גרסאות']].map(([v,n])=><TabsTrigger value={v} key={v}>{n}</TabsTrigger>)}</TabsList>
 {migrationNotice&&<div className="notice info" role="status">{migrationNotice}</div>}{researchScenario&&<div className="notice info"><strong>תרחיש מחקר פעיל · {researchScenario.horizon} חודשים</strong><p>שינוי חזוי בממוצעי השוק הוחל על ריביות הייחוס הקבועות. ריבית אישית עדיין אינה נחזית; מסלולי הצעה ונעילה נשמרים.</p><button className="text-button" onClick={()=>{setRates(researchScenario.baseRates);setResearchScenario(null);setRateOrigin(o=>({...o,basis:"ריביות הבסיס לפני תרחיש המחקר"}));setResult(null);setTab("algorithm");toast.info("ריביות החיפוש הוחזרו לבסיס. יש להריץ מחדש כדי לשנות את התמהיל.")}}>חזרה לריביות הבסיס לחיפוש</button></div>}<div className="workflow-status"><span>נתוני תיק → ריביות ומגבלות → השוואה → עמידות ושמירה</span><strong>{eligibility.valid?'התמהיל עומד בבדיקות הפעילות':'נדרשת בדיקת נתונים או מגבלות'}</strong></div>{calculationErrors.length>0&&<div className="notice" role="status"><strong>התוצאה אינה תקפה להחלטה</strong>{calculationErrors.map(e=><div key={e}>{e}</div>)}{!summary&&<p>יש להשלים את הנתונים החסרים ולוודא שסכומי המסלולים תואמים לתיק.</p>}</div>}
 <TabsContent value="workspace"><div className="work-grid"><section>{calculationErrors.length>0?<div className="notice"><strong>הסיכום חלקי עד להשלמת הנתונים</strong>{trackErrors.map(e=><div key={e}>{e}</div>)}</div>:summary&&<><div className="lead-result"><div><span className="eyebrow">{result?.candidates.length?(selectedId===result.candidates[0].id?'מובילה לפי המשקולות — תחת הנחות המחיר':'החלופה שבחרת'):'התמהיל הנוכחי'}</span><h2>החזר חודשי בתנאים הנוכחיים</h2><div className="hero-number">{money(summary.current)} <small>₪</small></div><p>{summary.current<=caseData.target?`${money(caseData.target-summary.current)} ₪ מתחת ליעד`:`${money(summary.current-caseData.target)} ₪ מעל היעד`} · {tracks.length} מסלולים</p></div><div className="lead-note"><strong>{result?.candidates.length?`${money(result.feasible)} חלופות עומדות במגבלות`:'כל נתון. כל הנחה. גלויים.'}</strong><p>{result?.scope??'אפשר לערוך את התמהיל או לחפש חלופות לפי העדפותיך.'}</p><button className="text-button" onClick={()=>setTab('algorithm')}>עריכת האלגוריתם</button></div></div><div className="metrics"><div><span>סך תשלומים {forecast.mode==='flat'?'בתנאים נוכחיים':'חזוי'}</span><strong>{summary.complete?money(summary.total):'לא זמין'} ₪</strong></div><div><span>החזר מרבי חזוי</span><strong>{summary.complete?money(summary.peak):'לא זמין'} ₪</strong><small>חודש {summary.peakMonth} · אינו תקרה מובטחת</small></div><div><span>יחס החזר להכנסה פנויה</span><strong>{aff.disposable>0?percent((summary.ptiPayment+aff.sameProperty)/aff.disposable*100):'דורש השלמה'}</strong><small>לפי החזר רגולטורי</small></div></div>{summary.maturity>0&&<div className="notice maturity"><strong>תשלום קרן בסיום מסלולי הבולט: {money(summary.maturity)} ₪</strong><div>נוסף לתשלומים השוטפים ומוצג בנפרד מההחזר החודשי המרבי.</div></div>}<div className="section-heading"><h2>ההחזר לאורך חודשי ההלוואה</h2><span className="muted">תחזית {forecast.curve.id} · ₪ לחודש</span></div>{summary.complete?<Chart data={chartData} keys={[["payment","תוואי בסיס",COLORS[0]],["stress",`ריבית +${scenarioShock}%`,COLORS[4]]]} budget={caseData.target}/>:<p className="notice">אין תחזית מלאה לכל המסלולים.</p>}</>}
 <div className="section-heading"><h2>מרכיבים את התמהיל</h2><div className="button-row"><button className="text-button" onClick={()=>setShowSchedule(true)} disabled={!summary||calculationErrors.length>0}>לוח סילוקין</button><button className="secondary icon-button" onClick={()=>{setResult(null);setTracks(t=>[...t,makeTrack('fixed',100000,rates.fixed)])}}><Plus size={16}/>מסלול</button></div></div><Table><TableHeader><TableRow><TableHead>מסלול</TableHead><TableHead>סכום ₪</TableHead><TableHead>ריבית נומינלית</TableHead><TableHead>חודשים</TableHead><TableHead>פרטים</TableHead></TableRow></TableHeader><TableBody>{tracks.map((t,i)=><TableRow key={t.id}><TableCell><span className="track-name"><i style={{background:COLORS[i%5]}}/>{TRACKS[t.kind]}</span><small>{methods[t.method]} · {t.source==='offer'?'הצעה שהוזנה':t.source==='manual'?'הנחה ידנית':'ריבית ייחוס'}{isVariable(t.kind)?` · עדכון ${t.resetMonths} ח׳`:''}</small></TableCell><TableCell><input className="table-input" aria-label={`סכום מסלול ${i+1}`} type="number" value={Number.isFinite(t.amount)?t.amount:''} onChange={e=>updateTrack(t.id,{amount:e.target.value===''?NaN:Number(e.target.value)})}/></TableCell><TableCell><input className="table-input narrow" aria-label={`ריבית מסלול ${i+1}`} type="number" step=".01" value={Number.isFinite(t.rate)?Number(t.rate.toFixed(4)):''} onChange={e=>updateTrack(t.id,{rate:e.target.value===''?NaN:Number(e.target.value),source:'manual'})}/></TableCell><TableCell><input className="table-input narrow" aria-label={`חודשים מסלול ${i+1}`} type="number" value={Number.isFinite(t.months)?t.months:''} onChange={e=>updateTrack(t.id,{months:e.target.value===''?NaN:Number(e.target.value)})}/></TableCell><TableCell><button className="text-button" onClick={()=>setSelectedTrack(t.id)}>עריכה</button></TableCell></TableRow>)}</TableBody></Table>
 <div className="section-heading"><h2>החלופות שלך</h2><span className="muted">{result?`${money(result.tested)} נסרקו · ${money(result.verified)} אומתו`:'ממתינות להרצה'}</span></div>{result?.errors.length?<div className="notice">{result.errors.map(e=><div key={e}>{e}</div>)}{result.nearest&&<p>ההחזר הנמוך בסינון המקורב (לא חלופה מאומתת): {money(result.nearest.first)} ₪. הוא אינו בהכרח עומד בשאר המגבלות.</p>}</div>:null}{result?.candidates.length?<><Toggle label="הצגת כל התקופות, כולל הרכבים חוזרים" checked={showAllTerms} onChange={v=>{setShowAllTerms(v);setVisibleCount(12)}}/><p className="muted">{showAllTerms?'כל החלופות לפי ציון':'מוצגת החלופה בעלת הציון הגבוה ביותר מכל הרכב מסלולים ואחוזים'}</p><div className="alternatives">{displayedCandidates.slice(0,visibleCount).map((c,i)=><button className={`alternative ${selectedId===c.id?'selected':''}`} key={c.id} onClick={()=>{setTracks(c.tracks);setSelectedId(c.id);setVersionLabel('חלופה '+(i+1))}}><span className="alternative-index">{String(i+1).padStart(2,'0')}</span><div><strong>{i===0?'מובילה לפי המשקולות':`חלופה ${i+1}`}</strong><small>{c.tracks.map(t=>`${TRACKS[t.kind]} ${money(t.amount/caseData.loan*100)}% · ${t.months} ח׳`).join(' / ')}</small></div><div><strong>{money(c.first)} ₪</strong><small>החזר ראשון</small></div><div><strong>{money(c.total)} ₪</strong><small>סך התשלומים</small></div><div><strong>{money(c.score,1)}</strong><small>ציון יחסי · שיא {money(c.peak)} ₪</small></div></button>)}</div>{visibleCount<displayedCandidates.length&&<button className="secondary" onClick={()=>setVisibleCount(n=>n+24)}>הצגת חלופות נוספות ({money(displayedCandidates.length-visibleCount)} נותרו)</button>}<p className="muted">מוצגות {Math.min(visibleCount,displayedCandidates.length)} מתוך {money(displayedCandidates.length)} ברשימה זו · {money(result.feasible)} חלופות מאומתות ברשימה המלאה. נסרקו {money(result.tested)} תמהילים ייחודיים; {money(result.screenedFeasible)} עברו סינון מקורב. הציון יחסי לחלופות שאומתו בהרצה זו. שינוי תקופות או משקלות עשוי לשנות את הדירוג. הריביות אינן מתומחרות מחדש לפי גודל המסלול.</p></>:<div className="empty-note">הגדירו יעד חודשי ומשקולות, והפעילו את החיפוש. תוצאה שאינה עומדת במגבלת חובה תוצג כלא ישימה.</div>}
 </section><aside className="side-panel"><p className="eyebrow">הפרמטרים שלך</p><h2>הגבולות שבתוכם מחפשים</h2><Num label="יעד החזר חודשי ₪" value={caseData.target} onChange={target=>updateCase({target})} step={100}/><Toggle label="היעד הוא תקרה מחייבת" checked={cfg.strictBudget} onChange={strictBudget=>updateCfg({strictBudget})}/><div className="side-fact"><span>סכום המשכנתא</span><strong>{money(caseData.loan)} ₪</strong></div><div className="side-fact"><span>מימון / הכנסה פנויה</span><strong>{percent(aff.ltv*100)} / {money(aff.disposable)} ₪</strong></div><div className="weight-mini">{['עלות כוללת','החזר חודשי','יציבות'].map((l,i)=><div key={l}><span>{l}</span><div><i style={{width:`${cfg.weights[i]}%`,background:COLORS[i]}}/></div><b>{cfg.weights[i]}</b></div>)}</div><button className="text-button icon-button" onClick={()=>setTab('algorithm')}><SlidersHorizontal size={16}/>כל פרמטרי האלגוריתם</button><hr/><h3>מה חשוב לבדוק</h3>{[...errors,...aff.warnings,...(summary?.warnings??[])].slice(0,6).map((w,i)=><p className="insight" key={i}><Info size={17}/>{w}</p>)}<div className="source-stamp"><FileCheck2 size={20}/><div><strong>חישוב שאפשר לשחזר</strong><small>מודל {MODEL_VERSION}<br/>תחזית {forecast.curve.id}<br/>ריביות לחיפוש: {rateOrigin.basis} · {rateOrigin.bank} · {rateOrigin.month}</small></div></div></aside></div></TabsContent>
 <TabsContent value="intake"><div className="work-grid"><section><div className="section-heading"><h2>העסקה והלווים</h2><button className="secondary" onClick={()=>setShowImport(true)}>קליטת שאלון</button></div><div className="form-grid"><label className="field">שם התיק<input className="field-input text-input" value={caseData.name} maxLength={100} onChange={e=>updateCase({name:e.target.value})}/></label><Pick label="סוג רכישה" value={caseData.purpose} onChange={v=>updateCase({purpose:v as Case['purpose']})} options={[["unknown","יש לבחור סוג רכישה"],["single","דירה יחידה"],["replacement","דירה חליפית"],["investment","דירה להשקעה"]]}/><Num label="שווי הנכס ₪" value={caseData.property} onChange={property=>updateCase({property})}/><Num label="סכום משכנתא ₪" value={caseData.loan} onChange={loan=>updateCase({loan})}/><Num label="יעד החזר ₪" value={caseData.target} onChange={target=>updateCase({target})}/><Num label="עמלות בתחילת ההלוואה ₪" value={caseData.fees} onChange={fees=>updateCase({fees})}/></div><Toggle label="הלווה יתגורר בנכס הנרכש" checked={caseData.occupies} onChange={occupies=>updateCase({occupies})}/><div className="section-heading"><h2>הכנסות נטו</h2><button className="secondary" onClick={()=>updateCase({income:[...caseData.income,{id:crypto.randomUUID(),label:'הכנסה נוספת',declared:0,recognized:0,status:'review'}]})}>הוספת הכנסה</button></div>{caseData.income.map((x,i)=><div className="input-row" key={x.id}><label className="field">מקור<input className="field-input text-input" value={x.label} onChange={e=>updateCase({income:caseData.income.map((a,j)=>j===i?{...a,label:e.target.value}:a)})}/></label><Num label={`נטו מוצהר ${i+1}`} value={x.declared} onChange={v=>updateCase({income:caseData.income.map((a,j)=>j===i?{...a,declared:v}:a)})}/><Num label={`סכום מוכר ${i+1}`} value={x.recognized} onChange={v=>updateCase({income:caseData.income.map((a,j)=>j===i?{...a,recognized:v}:a)})}/><Pick label={`מצב הכנסה ${i+1}`} value={x.status} onChange={v=>updateCase({income:caseData.income.map((a,j)=>j===i?{...a,status:v as any}:a)})} options={[["verified","אומתה ונכללת"],["review","דורשת בדיקה"],["excluded","אינה נכללת"]]}/><button className="icon-only" aria-label={`הסרת הכנסה ${i+1}`} onClick={()=>updateCase({income:caseData.income.filter((_,j)=>i!==j)})}><Trash2 size={16}/></button></div>)}<p className="muted">הזינו סכום חודשי נטו, לאחר בדיקת המשכיות ואסמכתאות. הכנסה שנתית מחולקת ב־12. יש למנוע ספירה כפולה של רווחי חברה ודיבידנדים.</p><div className="section-heading"><h2>התחייבויות קיימות</h2><button className="secondary" onClick={()=>updateCase({debts:[...caseData.debts,{id:crypto.randomUUID(),label:'התחייבות',payment:0,remainingMonths:null,kind:'debt',verifiedRepaid:false}]})}>הוספת התחייבות</button></div>{caseData.debts.map((d,i)=><div className="debt-row" key={d.id}><div className="input-row"><label className="field">תיאור<input className="field-input text-input" value={d.label} onChange={e=>updateCase({debts:caseData.debts.map((x,j)=>j===i?{...x,label:e.target.value}:x)})}/></label><Num label={`תשלום התחייבות ${i+1}`} value={d.payment} onChange={v=>updateCase({debts:caseData.debts.map((x,j)=>j===i?{...x,payment:v}:x)})}/><Num label={`חודשים שנותרו ${i+1}`} value={d.remainingMonths??NaN} onChange={v=>updateCase({debts:caseData.debts.map((x,j)=>j===i?{...x,remainingMonths:Number.isNaN(v)?null:v}:x)})} help="ריק = לא ידוע"/><Pick label={`סוג התחייבות ${i+1}`} value={d.kind} onChange={v=>updateCase({debts:caseData.debts.map((x,j)=>j===i?{...x,kind:v as any}:x)})} options={[["debt","הלוואה / ליסינג / מזונות"],["rent","שכר דירה משולם"],["sameProperty","משכנתא על אותו נכס"],["otherProperty","משכנתא על נכס אחר"],["repaid","מסולקת בעסקה"]]}/><button className="icon-only" aria-label={`הסרת התחייבות ${i+1}`} onClick={()=>updateCase({debts:caseData.debts.filter((_,j)=>i!==j)})}><Trash2 size={16}/></button></div>{d.kind==='sameProperty'&&<Num label={`יתרת חוב על אותו נכס ${i+1}`} value={d.balance??NaN} onChange={v=>updateCase({debts:caseData.debts.map((x,j)=>j===i?{...x,balance:Number.isFinite(v)?v:null}:x)})} help="נכללת במימון הכולל בנוסף לבקשה החדשה"/>}{d.kind==='repaid'&&<Toggle label="מקור הסילוק והמועד אומתו" checked={d.verifiedRepaid} onChange={v=>updateCase({debts:caseData.debts.map((x,j)=>j===i?{...x,verifiedRepaid:v}:x)})}/>}</div>)}<div className="notice info">התחייבויות מעל 18 חודשים מופחתות מההכנסה. משכנתא על אותו נכס שנותרו לה מעל 18 חודשים מצטרפת להחזר. שכר דירה נכלל גם בתקופה קצרה אם הלווה לא יתגורר בנכס הנרכש.</div></section><aside className="side-panel"><h2>התמונה הפיננסית</h2>{[['הכנסה מוכרת',aff.recognized],['התחייבויות להפחתה',aff.commitments],['הכנסה פנויה',aff.disposable],['החזר נוסף על אותו נכס',aff.sameProperty],['הון עצמי נדרש בעסקה',caseData.property-caseData.loan]].map(([l,v])=><div className="side-fact" key={l}><span>{l}</span><strong>{money(Number(v))} ₪</strong></div>)}<p className="muted">מגבלת מימון: {percent(aff.maxLtv*100)}<br/>הכנסה שסומנה לבדיקה אינה נחשבת מאומתת.</p>{[...errors,...aff.warnings].map((e,i)=><p className="notice" key={i}>{e}</p>)}<button className="primary" onClick={()=>setTab('algorithm')}>המשך לריביות ולמגבלות</button></aside></div></TabsContent>
 <TabsContent value="algorithm"><ResearchPanel busy={busy} onApply={applyResearch}/><QuotePanel caseData={caseData} tracks={tracks} data={data} onApply={q=>{setCase(q.caseData);setTracks(q.tracks.map(t=>({...t,locked:true,source:'offer'})));setBank(q.bank);setResult(null);setTab('workspace');setVersionLabel('הצעת בנק מתועדת');}}/><div className="work-grid"><section><div className="section-heading"><div><p className="eyebrow">ALGORITHM STUDIO · {MODEL_VERSION}</p><h2>מה הופך תמהיל לאופטימלי עבורך?</h2></div><button className="text-button" onClick={()=>updateCfg(defaultConfig)}>איפוס העדפות</button></div><div className="weights-editor">{['עלות כוללת נמוכה','החזר חודשי נמוך','יציבות בתרחיש ריבית'].map((l,i)=><div className="weight-editor" key={l}><div><strong>{l}</strong><span>{cfg.weights[i]}</span></div><Slider dir="rtl" aria-label={l} min={0} max={100} step={5} value={[cfg.weights[i]]} onValueChange={v=>{const weights=[...cfg.weights] as [number,number,number];weights[i]=v[0];updateCfg({weights})}}/></div>)}</div><p className="muted">המשקולות מנורמלות אוטומטית. יציבות נמדדת לפי הפער בין ההחזר הראשון להחזר השיא בתרחיש ריבית של 2 נקודות אחוז נוספות.</p><div className="section-heading"><h2>מגבלות החיפוש</h2></div><div className="form-grid"><Num label="מקסימום משתנה %" value={cfg.maxVariable} max={66.66} step={.01} onChange={maxVariable=>updateCfg({maxVariable:Math.min(66.66,maxVariable)})}/><Num label="מקסימום צמוד למדד %" value={cfg.maxIndexed} max={100} onChange={maxIndexed=>updateCfg({maxIndexed})}/><Num label="יחס החזר מרבי %" value={cfg.maxPti} max={50} onChange={maxPti=>updateCfg({maxPti:Math.min(50,maxPti)})}/><Num label="תקופה מינימלית בשנים" value={cfg.minYears} min={5} max={30} onChange={minYears=>updateCfg({minYears})}/><Num label="תקופה מרבית בשנים" value={cfg.maxYears} min={5} max={30} onChange={maxYears=>updateCfg({maxYears})}/><Pick label="דיוק חלוקת התמהיל" value={String(cfg.grid)} options={[["5","צעדים של 5%"],["10","צעדים של 10%"],["20","צעדים של 20%"]]} onChange={v=>updateCfg({grid:Number(v)})}/><Num label="תקרת החזר חזוי ₪" value={cfg.maxPeak} onChange={maxPeak=>updateCfg({maxPeak})} help="0 = ללא תקרה נוספת"/><Num label="יעד החזר חודשי ₪" value={caseData.target} onChange={target=>updateCase({target})}/></div><Toggle label="היעד החודשי הוא מגבלת חובה" checked={cfg.strictBudget} onChange={strictBudget=>updateCfg({strictBudget})}/><div className="section-heading"><h2>מסלולים וריביות לחיפוש</h2><div className="button-row"><Pick label="בנק לייחוס" value={bank} options={data.banks.map(b=>[b,b])} onChange={setBank}/><button className="secondary" onClick={applyMarket}>טעינת ממוצעי {data.equatorEnd}</button></div></div><p className="notice info">ממוצעי קו המשווה הומרו מריבית שנתית מתואמת לריבית נומינלית. אלו ריביות ייחוס; שינוי סכום או תקופה עשוי לשנות את מחיר ההצעה בפועל.</p>{kinds.map(k=><div className="rate-row" key={k}><Toggle label={TRACKS[k]} checked={cfg.enabled.includes(k)} onChange={b=>updateCfg({enabled:b?[...cfg.enabled,k]:cfg.enabled.filter(x=>x!==k)})}/><Num label={`ריבית לחיפוש — ${TRACKS[k]}`} value={rates[k]} step={.01} max={30} onChange={v=>{setResearchScenario(null);setRates(r=>({...r,[k]:v}));setRateOrigin(o=>({...o,basis:'הנחות ידניות'}));setResult(null)}}/></div>)}<div className="section-heading"><h2>התחזית שבה משתמשים</h2></div><div className="form-grid"><Pick label="בסיס תחזית" value={forecast.mode} onChange={v=>{setForecast(f=>({...f,mode:v as any}));setResult(null)}} options={[["boi","עקומי בנק ישראל"],["flat","תנאים נוכחיים ללא שינוי"],["custom","אינפלציה ידנית"]]}/><Pick label="עיגול ריבית חזויה" value={forecast.rateDecimals===undefined?'full':String(forecast.rateDecimals)} options={[['full','ללא עיגול ביניים'],['2','שתי ספרות אחרי הנקודה'],['3','שלוש ספרות']]} onChange={v=>{setForecast(f=>({...f,rateDecimals:v==='full'?undefined:Number(v)}));setResult(null)}}/><Pick label="גרסת עקום" value={forecast.curve.id} options={curveOptions} onChange={v=>{pinSource('forecast');setForecast(f=>({...f,curve:data.curves.find(c=>c.id===v)! as Curve}));setResult(null)}}/>{forecast.mode==='custom'&&<Num label="אינפלציה שנתית %" value={forecast.inflation} min={-5} max={20} step={.1} onChange={inflation=>{setForecast(f=>({...f,inflation}));setResult(null)}}/>}</div><div className="methodology"><h3>אפשר לבדוק את הדרך לתוצאה</h3><ol><li>מסננים לפי מימון, יחס החזר, חשיפה ותקרות שהוגדרו.</li><li>מסננים תזרימים בקירוב; מאמתים עד 120 חלופות מובילות ומגוונות בלוחות מדויקים לאגורה.</li><li>מנרמלים עלות, החזר ורגישות ומחשבים ציון לפי המשקולות.</li><li>מציגים גם חלופות שאינן נשלטות בכל שלושת היעדים.</li></ol><p>השינוי בעוגן מחושב מתשואות עתידיות הנגזרות מהעקום. עוגן חוזי ומרווח שהוזנו מקבלים קדימות. ללא נתון חוזי, המרווח מסומן כאומדן. החישוב מניח חודשים מלאים ותשלום בסוף חודש. ההחזר הנוכחי מוצג ללא שינויי מדד עתידיים; בתזרים התחזית המדד חל כבר בתום החודש הראשון. עקומי הריבית האפקטיבית מומרים לנומינלית לפני שילוב עם מרווח חוזי. התזרים מעוגל לאגורות בכל חודש; לוח בנק בפועל עשוי להשתנות לפי ימי ערך, רצפת מדד וכללי החוזה. ניתן לבחור עיגול נוסף לריבית חזויה.</p><a target="_blank" rel="noreferrer" href="https://www.boi.org.il/media/i5jbijyv/451_21.pdf">נוסחאות המקור — הוראה 451, תוספת 4</a><p className="muted">טרם אומן מודל לתמחור הצעות אישיות. לכך נדרשים אישורים עקרוניים אמיתיים ונתוני אימות נפרדים.</p></div></section><aside className="side-panel"><div className="sticky-summary"><h2>שיטת ההשוואה הפעילה</h2><div className="side-fact"><span>משקולות</span><strong>{cfg.weights.join(' / ')}</strong></div><div className="side-fact"><span>החזר מבוקש</span><strong>{money(caseData.target)} ₪</strong></div><div className="side-fact"><span>תנאי תקציב</span><strong>{cfg.strictBudget?'תקרה מחייבת':'העדפה בלבד'}</strong></div><button className="primary" disabled={busy} onClick={()=>{setTab('workspace');run()}}>{busy?'בוחן חלופות…':'הרצת האופטימיזציה'}</button><p className="muted">הדירוג משווה חלופות בתוך הרשת שנבדקה ותחת הריביות שהוזנו. אין כאן הבטחה לאופטימום בכל תמהיל אפשרי.</p></div></aside></div></TabsContent>
 <TabsContent value="scenarios">{calculationErrors.length===0?<div className="work-grid"><section>{!summary?.complete||!shockSummary?.complete?<div className="notice">התחזית חלקית; הגרפים הבאים כוללים הנחת תנאים נוכחיים במסלולים שלא ניתן לחזות. אין להשתמש בסיכום כתחזית מלאה.</div>:null}<div className="section-heading"><h2>ומה אם הריבית תשתנה?</h2><span className="pill">תרחיש רגישות</span></div><Chart data={chartData} keys={[["payment","תוואי בסיס",COLORS[0]],["stress",`שינוי של ${scenarioShock}%`,COLORS[4]]]} budget={caseData.target}/>{summary?.complete&&shockSummary?.complete&&<div className="metrics"><div><span>החזר שיא בתרחיש</span><strong>{money(shockSummary.peak)} ₪</strong></div><div><span>תוספת לסך התשלומים</span><strong>{money(shockSummary.total-summary.total)} ₪</strong></div><div><span>פער מהתקציב בשיא</span><strong>{money(shockSummary.peak-caseData.target)} ₪</strong></div></div>}<div className="section-heading"><h2>היתרה לאורך חיי ההלוואה</h2></div><Chart data={chartData} keys={[["balance","יתרת קרן חזויה",COLORS[1]]]}/><div className="notice info">ריבית קבועה נשארת קבועה. השינוי בתרחיש חל בפריים ובעדכון הבא של המסלולים המשתנים. לתרחיש מדד אפשר לבחור הנחה ידנית במסך האלגוריתם.</div><div className="section-heading"><h2>גרייס ופירעון מוקדם</h2></div><p>ערכו כל מסלול כדי להגדיר דחיית תשלומים, חודש פירעון וסכום. ניתן להפחית החזר או לקצר תקופה. עמלת הפירעון מוזנת בנפרד לפי נתוני הבנק.</p><button className="secondary" onClick={()=>{setTab('workspace');setSelectedTrack(tracks[0]?.id??null)}}>עריכת תנאי מסלול</button></section><aside className="side-panel"><h2>בונים תרחיש</h2><Num label="שינוי בריבית — נקודות אחוז" value={scenarioShock} min={-3} max={5} step={.25} onChange={setScenarioShock}/><Num label="חודש תחילת השינוי" value={scenarioMonth} min={2} max={360} onChange={setScenarioMonth}/><p className="muted">זהו מבחן רגישות לבחירתך, ולא תחזית להחלטות הריבית בפועל.</p><div className="source-stamp"><Info size={18}/><small>אין תמחור אוטומטי של עמלת פירעון מוקדם. כדי להציג חיסכון נטו במחזור יש להזין את עמלת הסילוק מהבנק.</small></div></aside></div>:<div className="empty-note">תרחישים יוצגו לאחר השלמת התיק ותמהיל שעומד במגבלות.</div>}</TabsContent>
 <TabsContent value="market"><div className="section-heading"><div><p className="eyebrow">BANK OF ISRAEL · DATA ROOM</p><h2>ריביות עם מקור, תאריך והקשר</h2></div><button className="secondary icon-button" onClick={sync} disabled={syncing}><RefreshCw size={16}/>{syncing?'מעדכן מקורות…':'רענון מקורות רשמיים'}</button></div>{loadWarning&&<div className="notice">{loadWarning}</div>}<div className="data-banner"><div><span>ריבית בנק ישראל שנקלטה</span><strong>{percent(data.policy.currentInterest,2)}</strong></div><div><span>פריים מאושר לחישוב</span><strong>{percent(approvedPolicy+1.5,2)}</strong></div><div><span>ממוצעי בנקים עד</span><strong>{data.equatorEnd}</strong></div><div><span>גרסת התחזית בהרצה</span><strong>{forecast.curve.id}</strong></div></div>{data.policy.currentInterest!==approvedPolicy&&<div className="notice"><p>נקלטה ריבית בנק ישראל חדשה. היא עדיין לא הוחלה על ההרצה.</p><button className="secondary" onClick={async()=>{try{await api('/api/preferences',{approvedPolicy:data.policy.currentInterest,sourceDate:data.policy.lastPublishedDate});const delta=data.policy.currentInterest-approvedPolicy;setApprovedPolicy(data.policy.currentInterest);setTracks(s=>s.map(t=>t.kind==='prime'?{...t,rate:t.rate+delta}:t));setRates(r=>({...r,prime:r.prime+delta}));setResult(null);toast.success('הבסיס החדש אושר והוחל על מסלולי הפריים בטיוטה')}catch(e){toast.error((e as Error).message)}}}>אישור החלת ריבית הפריים החדשה</button></div>}<div className="notice">הפרסום התחיל ב־03/2023. בקובץ שנקלט קיימים נתונים מ־{data.equatorStart} עד {data.equatorEnd}; חסרים {data.missingMonths} חודשים מההיסטוריה המבוקשת. החודשים החסרים אינם מושלמים בהערכה.</div><div className="market-filters"><Pick label="חודש השוואה" value={marketMonth} onChange={setMarketMonth} options={[...new Set(data.rates.map(r=>r.month))].sort().reverse().map(m=>[m,m])}/><Pick label="סוג ריבית" value={marketKind} onChange={setMarketKind} options={[...kinds.map(k=>[k,TRACKS[k]] as [string,string]),['irr','ריבית כוללת חזויה IRR']]}/><Pick label="בנק לגרף" value={marketBank} onChange={setMarketBank} options={data.banks.map(b=>[b,b])}/></div><div className="market-layout"><section><Chart data={data.rates.filter(r=>r.bank===marketBank).sort((a,b)=>a.month.localeCompare(b.month)).map(r=>({x:r.month,rate:r.rates[marketKind as keyof typeof r.rates]}))} keys={[["rate","ריבית שנתית מתואמת %",COLORS[0]]]}/></section><section><Table><TableHeader><TableRow><TableHead>בנק</TableHead><TableHead>ריבית מתואמת</TableHead><TableHead>נומינלית לחישוב</TableHead></TableRow></TableHeader><TableBody>{data.rates.filter(r=>r.month===marketMonth).map(r=>{const v=r.rates[marketKind as keyof typeof r.rates];return <TableRow key={r.bank}><TableCell>{r.bank}</TableCell><TableCell>{v==null?'לא פורסם':percent(v,2)}</TableCell><TableCell>{v==null||marketKind==='irr'?'—':percent(effectiveToNominal(v),3)}</TableCell></TableRow>})}</TableBody></Table></section></div><p className="muted">ממוצעי עסקאות שבוצעו, ללא בלון ומט״ח. אינם הצעה ללקוח מסוים. IRR כולל תחזיות לחודש הדיווח ולכן אינו זהה לריבית מסלול.</p><div className="section-heading"><h2>עקום התחזית והמדד</h2></div><div className="market-layout"><Chart data={forecast.curve.nominal.filter((_,i)=>i%12===11).map((n,i)=>({x:i+1,nominal:n,real:forecast.curve.real[i*12+11]}))} keys={[["nominal","תשואה נומינלית %",COLORS[0]],["real","תשואה ריאלית %",COLORS[1]]]}/><Chart data={data.cpi.month[0].date.slice().reverse().map(r=>({x:`${r.year}-${String(r.month).padStart(2,'0')}`,monthly:r.percent,yearly:r.percentYear}))} keys={[["monthly","שינוי חודשי במדד %",COLORS[0]],["yearly","שינוי שנתי במדד %",COLORS[1]]]}/></div><div className="section-heading"><h2>יומן מקורות</h2><button className="text-button" onClick={()=>download('mogi-market-snapshot.json',JSON.stringify(data))}>ייצוא תמונת נתונים</button></div><Table><TableHeader><TableRow><TableHead>מקור</TableHead><TableHead>תפקיד במערכת</TableHead><TableHead>נקלט</TableHead><TableHead>מקור רשמי</TableHead></TableRow></TableHeader><TableBody>{data.sources.map(s=><TableRow key={s.key}><TableCell>{s.label}<small className="hash">SHA256 {s.sha256.slice(0,14)}…</small></TableCell><TableCell>{{policyHistory:'היסטוריית ריבית בנק ישראל — MNT_RIB_BOI_D',policy:'בקרת בסיס הפריים — החלה באישור',equator:'השוואת בנקים וריביות ייחוס',forecast:'תוואי מדד ועוגנים עתידיים',market:`${data.marketRows} תצפיות מקור; ${data.market.length} סדרות נבחרות נשמרו`,zcm:`${data.zcm.length} סדרות רקע ורגישות נשמרו`,cpi:'מדד בפועל — בנפרד מתחזית',prepayLinked:'מקור עמלת יציאה; טרם חובר חישוב אוטומטי',prepayUnlinked:'מקור עמלת יציאה; טרם חובר חישוב אוטומטי'}[s.key]}</TableCell><TableCell>{s.fetchedAt.slice(0,10)}</TableCell><TableCell><a target="_blank" rel="noreferrer" href={s.url}>פתיחת המקור</a></TableCell></TableRow>)}</TableBody></Table><div className="section-heading"><h2>אימות מול המחשבונים</h2></div><p className="muted">מקרה ייחוס: 1,200,000 ₪ · 300 חודשים · 4.5% נומינלית · קבועה לא צמודה, שפיצר.</p><Table><TableHeader><TableRow><TableHead>בנק / מערכת</TableHead><TableHead>החזר ראשון ₪</TableHead><TableHead>סך תשלומים ₪</TableHead><TableHead>מה נבדק</TableHead></TableRow></TableHeader><TableBody><TableRow><TableCell>Wise</TableCell><TableCell>6,670</TableCell><TableCell>2,000,997</TableCell><TableCell>השוואה היסטורית. לאחר חיבור הליבה: פער של {money(coreComparison.variable.difference,2)} ₪ בתרחיש המשתנה ושל {money(coreComparison.fixed.difference,2)} ₪ בקבועה מול ייחוס ירושלים. הומרה ריבית אפקטיבית לנומינלית ונוסף עיגול חודשי לאגורות; אין אישור התאמה מלאה למחשבון בנק.</TableCell></TableRow>{checks.directlyExercised.map(b=><TableRow key={b.bank}><TableCell><a href={b.url} target="_blank" rel="noreferrer">{b.bank}</a></TableCell><TableCell>{money(b.firstPayment,2)}</TableCell><TableCell>{money(b.total,2)}</TableCell><TableCell>{b.notes}</TableCell></TableRow>)}</TableBody></Table><p className="muted">במזרחי־טפחות נבדק תמהיל ברירת המחדל וסלים אחידים. מסד, פאגי ואוצר החייל מפנים למחשבון הבינלאומי; יהב לשירותי טפחות. לא אותר מחשבון משכנתא ציבורי באתרי ONE ZERO ואש. עדיין נדרש אימות מול אישורים עקרוניים אנונימיים ותנאים חוזיים.</p></TabsContent>
 <TabsContent value="integrations"><div className="section-heading"><div><p className="eyebrow">WISE → MOGI</p><h2>פחות הזנה חוזרת. יותר מידע שימושי.</h2></div><button className="primary" onClick={()=>setShowImport(true)}>בדיקת קליטת שאלון</button></div><div className="integration-flow"><div><span>01</span><h3>שאלון דיגיטלי</h3><p>הלקוח מוסר פרטי נכס, בקשת משכנתא והכנסות של עד ארבעה לווים.</p></div><div><span>02</span><h3>טיוטה לבדיקה</h3><p>המערכת ממפה שדות כלכליים, מסמנת הכנסות לבדיקה ומציפה מידע חסר.</p></div><div><span>03</span><h3>אופטימיזציה</h3><p>לאחר אימות הנתונים, מחפשים תמהילים לפי התקציב, המגבלות וההעדפות.</p></div></div><Table><TableHeader><TableRow><TableHead>היכולת ב־Wise</TableHead><TableHead>התרומה למערכת שלך</TableHead><TableHead>המצב בפועל</TableHead></TableRow></TableHeader><TableBody><TableRow><TableCell>שאלון → מערכת חיצונית</TableCell><TableCell>פתיחת טיוטה מנתוני הלקוח ללא הקלדה מחדש</TableCell><TableCell>מיפוי מקומי פעיל; משלוח חי טרם חובר</TableCell></TableRow><TableRow><TableCell>API לקליטת לידים</TableCell><TableCell>טופס באתר שלך יכול ליצור ליד ב־Wise CRM</TableCell><TableCell>תועד; טרם בוצעה שליחה</TableCell></TableRow><TableRow><TableCell>AI API</TableCell><TableCell>ניתוח דוח אשראי באמצעות מפתח Gemini אישי</TableCell><TableCell>אינו API מאומת להפעלת האופטימייזר</TableCell></TableRow><TableRow><TableCell>כלי הטמעה</TableCell><TableCell>מחשבון, מחשבון זכאות וכלי תקציב לרוכש באתר שלך</TableCell><TableCell>דורשים מנוי, הפעלה ודומיין מאושר ב־Wise</TableCell></TableRow></TableBody></Table><div className="work-grid integration-details"><section><h2>מה צריך לוודא בקליטת השאלון</h2><ul><li>תקרת החזר רצויה והעדפות סיכון.</li><li>ב־Wise קיימים יתרה, תשלום ויתרת חודשים. טרם אומת שהם מגיעים במשלוח ה־API, ולכן יש לבדוק השלמה.</li><li>מסלולי משכנתא קיימים, עוגנים ומועדי שינוי ריבית.</li><li>תכניות פירעון מוקדם ומקור הכסף.</li></ul><p>אלו נתונים שמשפיעים על התמהיל ולכן צריך להשלים אותם במוגי. הכנסה שנקלטה משאלון נשארת במצב ״דורשת בדיקה״ עד לאימות.</p></section><aside className="notice"><strong>מה דרוש לחיבור חי</strong><p>דוגמת משלוח אמיתית ומצונזרת, מיקום אסימון האימות, מבנה המעטפת וכללי שליחה חוזרת. לאחר בדיקה אפשר להפעיל קבלה מאובטחת ולמנוע יצירת תיקים כפולים.</p><p>הטמעת מחשבון מציגה כלי בתוך האתר; היא אינה מוכיחה שניתן לקבל את תוצאותיו דרך API.</p></aside></div><a href="https://app.wisecard.co.il/x/User/profile#page_ai_api" target="_blank" rel="noreferrer">להגדרות החיבורים ב־Wise</a></TabsContent>
 <TabsContent value="history"><div className="section-heading"><h2>גרסאות שאפשר לחזור אליהן</h2><button className="primary icon-button" onClick={save} disabled={persisting||busy}><Save size={16}/>שמירת ההרצה הנוכחית</button></div><p className="muted">כל גרסה שומרת את נתוני התיק, המסלולים, ההנחות, עקום התחזית וחתימות המקורות. עדכון המקורות אינו משנה הרצה שמורה.</p>{saved.length?<Table><TableHeader><TableRow><TableHead>תיק</TableHead><TableHead>נשמר</TableHead><TableHead>תחזית</TableHead><TableHead>פעולה</TableHead></TableRow></TableHeader><TableBody>{saved.map(r=><TableRow key={r.id}><TableCell>{r.name}</TableCell><TableCell>{new Date(r.created_at).toLocaleString('he-IL')}</TableCell><TableCell>{r.payload.forecast?.curve?.id}</TableCell><TableCell><button className="text-button" onClick={()=>restore(r)}>שחזור</button></TableCell></TableRow>)}</TableBody></Table>:<div className="empty-note">עוד אין גרסאות שמורות. שמרו הרצה כדי לחזור לאותו בסיס חישוב גם אחרי עדכון נתונים.</div>}<button className="secondary icon-button" onClick={()=>download('mogi-calculation.json',JSON.stringify(state(),null,2))}><Download size={16}/>ייצוא התיק הנוכחי</button></TabsContent>
 </Tabs></fieldset><footer className="app-footer"><span>Mogi · {MODEL_VERSION}</span><span>נתוני דוגמה ניתנים לעריכה · ממוצעי שוק אינם הצעה אישית · תחזיות אינן הבטחה</span><a href="https://www.boi.org.il/media/hjrlkrse/h2852.pdf" target="_blank" rel="noreferrer">כללי בסיס — הוראה 329</a></footer>
 <Dialog open={!!active} onOpenChange={v=>{if(!v)setSelectedTrack(null)}}><DialogContent className="mogi-dialog" dir="rtl"><DialogTitle>תנאי המסלול</DialogTitle><DialogDescription>הריבית הכוללת היא הנתון הראשי. עוגן ומרווח חוזיים מאפשרים תחזית מדויקת יותר.</DialogDescription>{active&&<><div className="form-grid"><Pick label="סוג המסלול" value={active.kind} options={Object.entries(TRACKS)} onChange={v=>updateTrack(active.id,{kind:v as TrackKind,resetMonths:v==='prime'?1:60})}/><Pick label="שיטת החזר" value={active.method} options={Object.entries(methods)} onChange={v=>updateTrack(active.id,{method:v as any})}/><Num label="סכום מסלול ₪" value={active.amount} onChange={amount=>updateTrack(active.id,{amount})}/><Num label="ריבית שנתית נומינלית %" value={active.rate} step={.01} max={30} onChange={rate=>updateTrack(active.id,{rate,source:'manual'})}/><Num label="תקופה בחודשים" value={active.months} max={360} min={1} onChange={months=>updateTrack(active.id,{months})}/><Pick label="מקור הריבית" value={active.source} options={[["estimate","ריבית ייחוס מהשוק"],["manual","הנחה ידנית"],["offer","הצעה אישית שהוזנה"]]} onChange={v=>updateTrack(active.id,{source:v as any})}/></div>{isVariable(active.kind)&&<><div className="form-grid"><Num label="עדכון ריבית כל מספר חודשים" value={active.resetMonths} min={1} max={120} onChange={resetMonths=>updateTrack(active.id,{resetMonths})}/><Num label="חודשים עד השינוי הבא" value={active.nextReset??NaN} min={1} max={120} help="נדרש בהלוואה קיימת" onChange={v=>updateTrack(active.id,{nextReset:Number.isNaN(v)?undefined:v})}/><Num label="עוגן במועד קביעת הריבית %" value={active.anchor??NaN} min={-5} max={30} step={.01} onChange={v=>updateTrack(active.id,{anchor:Number.isNaN(v)?undefined:v})}/><Num label="מרווח חוזי בנקודות אחוז" value={active.spread??NaN} min={-10} max={20} step={.01} onChange={v=>updateTrack(active.id,{spread:Number.isNaN(v)?undefined:v})}/><label className="field">תאריך קביעת העוגן<input className="field-input" type="date" value={active.anchorDate??''} onChange={e=>updateTrack(active.id,{anchorDate:e.target.value})}/></label></div><Toggle label="זוהי הלוואה קיימת" checked={active.existing??false} onChange={existing=>updateTrack(active.id,{existing})}/></>}<Toggle label="שמירת המסלול ללא שינוי בחיפוש" checked={active.locked??false} onChange={locked=>updateTrack(active.id,{locked})}/><p className="muted">הצעה אישית, מסלול קיים, גרייס, בולט או פירעון מתוכנן נשמרים אוטומטית בחיפוש.</p><h3>גרייס — כלול בתקופה הכוללת</h3><div className="form-grid"><Pick label="סוג גרייס" value={active.grace} options={[["none","ללא גרייס"],["partial","תשלום ריבית בלבד"],["full","דחיית קרן וריבית"]]} onChange={v=>updateTrack(active.id,{grace:v as any,graceMonths:v==='none'?0:12})}/>{active.grace!=='none'&&<Num label="חודשי גרייס" value={active.graceMonths} min={1} max={active.months-1} onChange={graceMonths=>updateTrack(active.id,{graceMonths})}/>}</div><h3>פירעון מוקדם מתוכנן</h3><div className="form-grid"><Num label="סכום פירעון ₪" value={active.prepayAmount??0} onChange={prepayAmount=>updateTrack(active.id,{prepayAmount,prepayMonth:active.prepayMonth??60})}/><Num label="לאחר תשלום בחודש" value={active.prepayMonth??60} min={1} max={active.months} onChange={prepayMonth=>updateTrack(active.id,{prepayMonth})}/><Num label="עמלת פירעון מהבנק ₪" value={active.prepayFee??0} onChange={prepayFee=>updateTrack(active.id,{prepayFee})}/><Pick label="אופן התאמה לאחר פירעון" value={active.prepayMode??'payment'} options={[["payment","הפחתת החזר"],["term","קיצור תקופה"]]} onChange={v=>updateTrack(active.id,{prepayMode:v as any})}/></div><p className="muted">בקיצור תקופה נשמר ההחזר עד לסילוק והחודש האחרון מותאם ליתרה. בגרייס מלא הריבית נצברת מדי חודש. יש לבדוק התאמה לתנאי החוזה.</p>{validateTrack(active).map(e=><p className="notice" key={e}>{e}</p>)}<div className="dialog-actions"><button className="primary" onClick={()=>setSelectedTrack(null)}>סיום עריכה</button><button className="text-button danger" onClick={()=>{setResult(null);setTracks(s=>s.filter(t=>t.id!==active.id));setSelectedTrack(null)}}>הסרת המסלול</button></div></>}</DialogContent></Dialog>
 <Dialog open={showSchedule} onOpenChange={setShowSchedule}><DialogContent className="mogi-dialog schedule-dialog" dir="rtl"><DialogTitle>לוח הסילוקין של התמהיל</DialogTitle><DialogDescription>תשלומים חזויים לפי הנתונים הנוכחיים · גרסת עקום {forecast.curve.id}</DialogDescription><button className="secondary icon-button" onClick={()=>{if(!summary||!eligibility.valid)return;const cols=['month','opening','principal','interest','indexation','regular','extra','fees','payment','balance'] as const;download('mogi-schedule.csv','\uFEFF'+'חודש,יתרה בתחילת חודש,קרן,ריבית,הצמדה,תשלום שוטף,פירעון נוסף,עמלה,סך תשלום,יתרת סגירה\n'+summary.rows.map(r=>cols.map(k=>r[k].toFixed(2)).join(',')).join('\n'),'text/csv;charset=utf-8')}}><Download size={16}/>ייצוא הלוח</button><div className="schedule-scroll"><Table><TableHeader><TableRow>{['חודש','יתרת פתיחה','קרן','ריבית','הצמדה','תשלום שוטף','פירעון נוסף','יתרת סגירה'].map(t=><TableHead key={t}>{t}</TableHead>)}</TableRow></TableHeader><TableBody>{summary?.rows.map(r=><TableRow key={r.month}><TableCell>{r.month}</TableCell>{[r.opening,r.principal,r.interest,r.indexation,r.regular,r.extra,r.balance].map((v,i)=><TableCell key={i}>{money(v,2)}</TableCell>)}</TableRow>)}</TableBody></Table></div></DialogContent></Dialog>
 <Dialog open={showImport} onOpenChange={setShowImport}><DialogContent className="mogi-dialog" dir="rtl"><DialogTitle>קליטת שאלון Wise לטיוטה</DialogTitle><DialogDescription>בדיקת מיפוי מקומית לפי המסמך של Wise. החיבור החי עדיין אינו פעיל.</DialogDescription><button className="text-button" onClick={()=>{setJsonInput(JSON.stringify({homevalue:'2,000,000',mortgage_request:'1,200,000',neches:'דירה יחידה',paycheck_1:'16,000',paycheck_2:'10,000',incomeType1:'שכירות',incomeAmount1:'3,000'},null,2));setDraft(null);setImportError('')}}>טעינת שאלון לדוגמה ללא פרטים מזהים</button><label className="field">נתוני השאלון JSON<textarea className="json-editor" dir="ltr" value={jsonInput} onChange={e=>{setJsonInput(e.target.value);setDraft(null)}} maxLength={100000}/></label><button className="secondary" onClick={()=>{try{setDraft(mapWiseQuestionnaire(JSON.parse(jsonInput)));setImportError('')}catch(e){setImportError((e as Error).message);setDraft(null)}}}>בדיקת הנתונים</button>{importError&&<p className="notice">{importError}</p>}{draft&&<><div className="notice info"><strong>{draft.caseData.income.length} מקורות הכנסה נקלטו לבדיקה</strong><p>נכס {money(draft.caseData.property)} ₪ · בקשה {money(draft.caseData.loan)} ₪</p><p>{draft.notice}</p></div><p>נדרש להשלים: {draft.missing.join(' · ')}</p><button className="primary" onClick={()=>{setCase(draft.caseData);setResult(null);setTab('intake');setShowImport(false);setVersionLabel('טיוטת שאלון לבדיקה');toast.success('נוצרה טיוטה; יש לאמת את ההכנסות ולהשלים התחייבויות')}}>פתיחת טיוטה לבדיקת יועץ</button></>}</DialogContent></Dialog>
 </main>;
}
